function solve(a){const b=a.filter(a=>a!=null);function c(a){while(true){const c=2*a+1;const d=c+1;let e=a;if(c<b.length&&b[c].val<b[e].val){e=c;}if(d<b.length&&b[d].val<b[e].val){e=d;}if(e===a){return;}[b[a],b[e]]=[b[e],b[a]];a=e;}}for(let i=Math.floor(b.length/2)-1;i>=0;i--){c(i);}const m={next:null};let d=m;while(b.length>0){const a=b[0];if(a.next!=null){b[0]=a.next;}else{const a=b.pop();if(b.length>0){b[0]=a;}}if(b.length>0){c(0);}d.next=a;d=a;}d.next=null;return m.next;}
